export type LegalDocKey = "privacy" | "terms" | "acceptable-use" | "terms-of-sale" | "child-safety" | "safeguarding" | "advertising" | "editorial";

/** A run of text: plain, bold, or a link (a site path, https:// URL or mailto:). */
